, "tension_fraction": 0.2549, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "moderate", "active_tension_exposure_cm2": 7.20, "eccentric_structural_stress": "standard", "meaningful_tension_duration": "reference", "sustained_isometric_tension": "none", "dominant_recovery_mechanisms": ["conventional_contractile_fatigue"], "high_force_lengthening_at_long_length": "none"}, {"R_m": 0.9500, "muscle": "brachialis", "rationale": "Holds the elbow angle as the rope is pulled toward the face rather than driving the movement through a loaded elbow range; the tension is positional and non-lengthening, so its fatigue is largely transient.", "maximum_fcsa_cm2": 44.05, "tension_fraction": 0.0876, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "low", "active_tension_exposure_cm2": 3.86, "eccentric_structural_stress": "minimal", "meaningful_tension_duration": "reference", "sustained_isometric_tension": "moderate", "dominant_recovery_mechanisms": ["low_level_positional_isometric_tension"], "high_force_lengthening_at_long_length": "none"}, {"R_m": 1.0000, "muscle": "trapezius_lower", "rationale": "Contributes actively to scapular retraction and depression through the movement range rather than holding a static position, giving a conventional dynamic profile at the reference value.", "maximum_fcsa_cm2": 14.98, "tension_fraction": 0.2336, "perfusion_constraint": "low", "force_development_profile": "controlled", "relative_tension_severity": "moderate", "active_tension_exposure_cm2": 3.50, "eccentric_structural_stress": "standard", "meaningful_tension_duration": "reference", "sustained_isometric_tension": "none", "dominant_recovery_mechanisms": ["conventional_contractile_fatigue"], "high_force_lengthening_at_long_length": "none"}, {"R_m": 0.9500, "muscle": "biceps_brachii", "rationale": "Maintains elbow position at low force without dynamic excursion or lengthening under load, so